pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Log lg;

    function setUp() public {
        lg = new Log();
        c = new C(address(lg));
    }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0) && actor != address(c));
        amount = bound(amount, c.MinDeposit() + 1, type(uint256).max / 2);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Deposit{value: amount}();

        // Universal rule: a successful Deposit above MinDeposit is recorded in the
        // Log's History with Sender == depositor and Val == deposited amount.
        (address sender, , uint256 val, ) = lg.History(0);
        assertTrue(sender == actor && val == amount);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 am, uint256 am2) public {
        vm.assume(am > 1 ether);
        bound(am, 1 ether + 1, 2 ether);
        vm.assume(am2 > 0);

        Reentrant attacker = new Reentrant{value: 3 * am}(c);
        bool ok;
        try attacker.attack(am, am2) { ok = true; } catch { ok = false; }

        // General rule: a CashOut of _am with _am <= caller balance must not revert
        // (deduction happens before the external call, so reentrant withdrawals
        // see the already-reduced balance and cannot corrupt it).
        assertTrue(ok);
    }
}

contract Reentrant {
    C c;
    bool reentered;

    constructor(C _c) payable {
        c = _c;
    }

    function attack(uint256 am, uint256 am2) external {
        c.Deposit{value: am}();
        c.CashOut(am);
    }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            (bool s, ) = address(c).call(
                abi.encodeWithSelector(c.CashOut.selector, msg.value)
            );
            s; // ignore result
        }
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    receive() external payable {}
    fallback() external payable {}

    function depositCreditsBalance(uint amount) public {
        require(amount > c.MinDeposit());
        require(address(this).balance >= amount);
        uint before_ = c.balances(address(this));
        c.Deposit{value: amount}();
        assert(c.balances(address(this)) == before_ + amount);
    }
}

